function toggleMenu(){document.getElementById("nav-menu").classList.toggle("active"),document.querySelector(".overlay").classList.toggle("active")}function toggleMobileDropdown(e){if(window.innerWidth<=768){e.nextElementSibling.classList.toggle("mobile-open")}}function converterTemperatura(){const e=document.getElementById("unidade-entrada").value,t=parseFloat(document.getElementById("temp-entrada").value);let n,o,l=0;if(isNaN(t))return document.getElementById("val-c").textContent="-",document.getElementById("val-f").textContent="-",void(document.getElementById("val-k").textContent="-");if("C"===e?n=t:"F"===e?n=5*(t-32)/9:"K"===e&&(n=t-273.15),o=9*n/5+32,l=n+273.15,document.getElementById("val-c").textContent=n.toFixed(1).replace(".",",")+"°C",document.getElementById("val-f").textContent=o.toFixed(1).replace(".",",")+"°F",document.getElementById("val-k").textContent=l.toFixed(1).replace(".",",")+"K","function"==typeof window.salvarCalculo){window.salvarCalculo("Calculadora de Temperatura",`Entrada: ${t}${e}`,`Resultados: ${n.toFixed(1)}°C | ${o.toFixed(1)}°F | ${l.toFixed(1)}K`)}}